import json
import re
import sys

# HTTP evidence is independent from strict organization identity inspection.
# The connector contract supplies an integral HTTP status and Boolean success.
try:
    httpStatus = int(sys.argv[4])
except (ValueError, TypeError):
    httpStatus = 0
requestSucceeded = sys.argv[5].strip().lower() == "true"
if not requestSucceeded or httpStatus != 200:
    statusCode = httpStatus if 300 <= httpStatus < 600 else 502
    lookupStatus = "api-failure"
    message = "Organization lookup API request failed"
    errorMessage = "The organization request failed or returned a non-200 response."
    organizationMoid, organizationJson, inspectionComplete = "", "{}", False
    safeCode, safeMessage = "", ""
    try:
        payload = json.loads(sys.argv[1])
        # Preserve the native String projection used by the old safe allowlists.
        def text(value):
            return value if isinstance(value, str) else json.dumps(value, separators=(",", ":"), ensure_ascii=False)
        code = text(payload["Code"]) if isinstance(payload, dict) and "Code" in payload else ""
        detail = text(payload["Message"]) if isinstance(payload, dict) and "Message" in payload else ""
        if re.fullmatch(r"[A-Za-z0-9_.:-]{1,128}", code):
            safeCode = code
        if re.fullmatch(r"[A-Za-z0-9 _.,:()/+\-]{1,500}", detail) and not re.search(r"authorization|password|secret|token|api.?key|bearer|https?://", detail, re.IGNORECASE):
            safeMessage = detail
    except Exception:
        pass
    if safeMessage:
        errorMessage = safeMessage
    resultJson = json.dumps({"status":"api-failure", "upstreamStatus":httpStatus, "Code":safeCode, "Message":safeMessage}, separators=(",", ":"))
else:
    import json
    import re
    import sys
    statusCode, lookupStatus, message = 502, "invalid-response", "Organization response is invalid"
    organizationMoid, organizationJson = "", "{}"
    inspectionComplete = False
    try:
        payload = json.loads(sys.argv[1])
        if not isinstance(payload, dict): raise ValueError("Organization response must be an object")
        count, rows = payload.get("Count"), payload.get("Results")
        if isinstance(count, bool) or not isinstance(count, int) or count < 0: raise ValueError("Count must be a nonnegative integer")
        if not isinstance(rows, list): raise ValueError("Results must be an array")
        if count != len(rows): raise ValueError("Count and Results length differ; the bounded page is incomplete")
        if count > 2: raise ValueError("Count exceeds the two-row lookup bound")
        if count == 0: statusCode, lookupStatus, message = 404, "not-found", "No organization matched the exact requested name"
        elif count != 1: statusCode, lookupStatus, message = 409, "ambiguous", "More than one organization matched the exact requested name"
        else:
            item = rows[0]
            if not isinstance(item, dict) or item.get("Name") != sys.argv[2]: raise ValueError("Organization Name does not match exactly")
            if item.get("ObjectType") != "organization.Organization" or item.get("ClassId") != "organization.Organization": raise ValueError("Organization discriminators do not match")
            moid = item.get("Moid")
            pattern = r"[0-9a-fA-F]{24}" if sys.argv[3] == "Hex24" else r"[A-Za-z0-9][A-Za-z0-9._~-]{0,127}"
            if not isinstance(moid, str) or re.fullmatch(pattern, moid) is None: raise ValueError("Organization Moid is missing or malformed")
            organizationMoid = moid
            projected = {key:item[key] for key in ("Moid", "Name", "ObjectType", "ClassId")}
            organizationJson = json.dumps(projected, separators=(",", ":"))
            resultJson = json.dumps({"Count":1,"Results":[projected]}, separators=(",", ":"))
            statusCode, lookupStatus, message = 200, "exact", "Organization resolved exactly"
        inspectionComplete = True
    except Exception as exc:
        statusCode, lookupStatus, message, inspectionComplete = 502, "invalid-response", str(exc), True
    errorMessage = "" if statusCode == 200 else message
    if statusCode != 200: resultJson = json.dumps({"status":lookupStatus,"error":message}, separators=(",", ":"))

import json
import sys
status = 'invalid'
failureCode = '422'
failureMessage = 'Create request mapping was rejected'
failureError = 'The request body could not be mapped safely.'
failureResult = '{}'
requestBody = ''
try:
    organizationMoid, definitionMoid, poolMoid, scheduleMoid = [x.strip() for x in sys.argv[1:5]]
    definition = json.loads(sys.argv[5])
    blueprints = json.loads(sys.argv[6])
    qualifiers = json.loads(sys.argv[7])
    tags = json.loads(sys.argv[8])
    definitionName = sys.argv[9]
    usePreferred = sys.argv[18] == 'true'
    version = int(sys.argv[11])
    deploymentName = sys.argv[12]
    descriptionValue = sys.argv[13]
    prefix = sys.argv[14]
    startIndex = int(sys.argv[15])
    digitCount = int(sys.argv[16])
    rollout = sys.argv[17]
    allowedQualifierKeys = {'resource.ChassisServersQualifier': {'ClassId', 'ObjectType', 'SlotIds'}, 'resource.DomainQualifier': {'ClassId', 'ObjectType', 'DomainNames', 'FabricInterConnectPids'}, 'resource.GpuQualifier': {'ClassId', 'ObjectType', 'GpuControllersRange', 'GpuEvaluationType', 'Pids', 'Vendor'}, 'resource.MemoryQualifier': {'ClassId', 'ObjectType', 'MemoryCapacityRange', 'MemoryUnitsRange'}, 'resource.NetworkAdaptorQualifier': {'ClassId', 'ObjectType', 'AdaptorsRange'}, 'resource.ProcessorQualifier': {'ClassId', 'ObjectType', 'CpuCoresRange', 'Pids', 'SpeedRange', 'Vendor'}, 'resource.OdataRuleSetQualifier': {'ClassId', 'ObjectType', 'Rules'}, 'resource.BladeQualifier': {'ClassId', 'ObjectType', 'AssetTags', 'ChassisAndSlotIdRange', 'ChassisPids', 'Pids', 'UserLabels'}, 'resource.RackServerQualifier': {'ClassId', 'ObjectType', 'AssetTags', 'Pids', 'RackIdRange', 'UserLabels'}, 'resource.TagQualifier': {'ClassId', 'ObjectType', 'ChassisTags', 'DomainProfileTags', 'ServerTags'}}
    definitionBlueprints = definition.get('Blueprints') or []
    byName = {}
    for entry in definitionBlueprints:
        if not isinstance(entry, dict) or not isinstance(entry.get('Name'), str):
            raise ValueError('The selected definition contains an invalid Blueprint reference.')
        byName.setdefault(entry['Name'], []).append(entry)
    seen = set()
    for override in blueprints:
        if not isinstance(override, dict) or override.get('ClassId') != 'workload.BlueprintInputReference' or override.get('ObjectType') != 'workload.BlueprintInputReference':
            raise ValueError('Every blueprint override needs matching workload.BlueprintInputReference discriminators.')
        name = override.get('Name')
        if not isinstance(name, str) or len(byName.get(name, [])) != 1 or name in seen:
            raise ValueError('Every override Name must map uniquely to one selected-definition blueprint and may appear once.')
        seen.add(name)
        expected = byName[name][0].get('Blueprint')
        supplied = override.get('Blueprint')
        if supplied not in (None, {}) and (not isinstance(supplied, dict) or not isinstance(expected, dict) or supplied.get('Moid') != expected.get('Moid')):
            raise ValueError('A supplied Blueprint relationship does not match the selected definition.')
    for qualifier in qualifiers:
        qualifierType = qualifier.get('ObjectType') if isinstance(qualifier, dict) else None
        if qualifierType not in allowedQualifierKeys or qualifier.get('ClassId') != qualifierType:
            raise ValueError('Every qualifier needs matching documented concrete discriminators.')
        unsupportedKeys = sorted(set(qualifier) - allowedQualifierKeys[qualifierType])
        if unsupportedKeys:
            raise ValueError('Qualifier ' + qualifierType + ' contains unsupported top-level keys: ' + ', '.join(unsupportedKeys) + '.')
    orgRef = {'ClassId': 'mo.MoRef', 'ObjectType': 'organization.Organization', 'Moid': organizationMoid}
    mapper = {'ClassId': 'workload.DefinitionMapper', 'ObjectType': 'workload.DefinitionMapper', 'DefinitionName': definitionName, 'Organization': orgRef, 'UsePreferredVersion': usePreferred}
    if not usePreferred:
        mapper['Version'] = version
    payload = {'ClassId': 'workload.WorkloadDeployment', 'ObjectType': 'workload.WorkloadDeployment', 'Name': deploymentName, 'WorkloadDefinitionReference': mapper, 'ResourcePool': {'ClassId': 'mo.MoRef', 'ObjectType': 'resourcepool.Pool', 'Moid': poolMoid}, 'WorkloadInstancePrefix': prefix, 'StartIndexForSuffix': startIndex, 'DigitCount': digitCount, 'Blueprints': blueprints, 'Qualifiers': qualifiers, 'RolloutStrategy': {'ClassId': 'workload.' + rollout + 'Deployment', 'ObjectType': 'workload.' + rollout + 'Deployment'}, 'Organization': orgRef, 'Tags': tags}
    if descriptionValue:
        payload['Description'] = descriptionValue
    if scheduleMoid:
        payload['SchedulePolicy'] = {'ClassId': 'mo.MoRef', 'ObjectType': 'scheduler.SchedulePolicy', 'Moid': scheduleMoid}
    requestBody = json.dumps(payload, separators=(',', ':'), ensure_ascii=False, allow_nan=False)
    if json.loads(requestBody) != payload or definition.get('Moid') != definitionMoid:
        raise ValueError('The request body or selected definition identity failed round-trip validation.')
    status = 'ready'
    failureCode = failureMessage = failureError = ''
    failureResult = '{}'
except Exception as exc:
    failureError = 'Create mapping failed closed before POST: ' + str(exc)
    failureResult = json.dumps({'error': failureMessage, 'details': failureError, 'mutationSent': False}, separators=(',', ':'))

import json
import re
import sys
status="invalid"; failureCode="502"; failureMessage="Created deployment response was invalid"; failureError="The create response could not be validated."; failureResult="{}"; createdMoid=""
try:
    item=json.loads(sys.argv[1]); expectedName=sys.argv[2]; orgMoid=sys.argv[3]; poolMoid=sys.argv[4]
    createdMoid=str(item.get("Moid","")).strip()
    if not re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9._~-]{0,127}",createdMoid): raise ValueError("Moid is missing or unsafe.")
    if item.get("ClassId")!="workload.WorkloadDeployment" or item.get("ObjectType")!="workload.WorkloadDeployment" or item.get("Name")!=expectedName: raise ValueError("Created identity does not match.")
    if not isinstance(item.get("Organization"),dict) or item["Organization"].get("Moid")!=orgMoid: raise ValueError("Organization relationship does not match.")
    if not isinstance(item.get("ResourcePool"),dict) or item["ResourcePool"].get("Moid")!=poolMoid: raise ValueError("ResourcePool relationship does not match the request.")
    if item.get("Status")!="Draft":
        failureCode="422"; failureMessage="Created deployment is not Draft"; failureError="POST created a record, but returned Status is not Draft. Inspect ValidationInformation before remediation."; failureResult=json.dumps({"error":failureMessage,"Moid":createdMoid,"Status":item.get("Status"),"ValidationInformation":item.get("ValidationInformation"),"mutationSent":True},separators=(",",":"))
    else:
        status="ready"; failureCode=failureMessage=failureError=""; failureResult="{}"
except Exception as exc:
    failureError="The create response failed validation after POST: "+str(exc); failureResult=json.dumps({"error":failureMessage,"details":failureError,"mutationSent":True},separators=(",",":"))

